def group_existing_tags(apps, schema_editor):
    from uuid import uuid5

    tag_model = apps.get_model("n26", "CampaignTag")
    for tag in tag_model.objects.select_related("receipt__intervention").iterator():
        intervention = tag.receipt.intervention
        index = next(
            (
                i
                for i, reward in enumerate(intervention.rewards)
                if reward.get("kind") == "tag"
                and reward.get("name") == tag.name
                and reward.get("icon") == tag.icon
                and reward.get("info", "") == tag.info
            ),
            None,
        )
        identity = f"tag:{index}" if index is not None else f"tag:{tag.pk}"
        tag_model.objects.filter(pk=tag.pk).update(
            assignment_key=uuid5(intervention.pk.to_uuid(), identity)
        )


